<section class="admin-card"><div class="card-head"><form class="admin-search" method="get"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?=e($search)?>" placeholder="Search products, codes or categories"><button>Search</button></form><a class="btn btn-primary" href="<?=e(url('admin/products/add'))?>"><i class="fa-solid fa-plus"></i> Add Product</a></div><div class="table-responsive"><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Status</th><th>Featured</th><th>Updated</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><div class="product-cell"><img src="<?=e(upload_url($product['main_image']))?>" alt=""><div><strong><?=e($product['name'])?></strong><small><?=e($product['product_code']?:$product['slug'])?></small></div></div></td><td><?=e($product['category_name'])?></td><td><span class="status status-<?=strtolower($product['status'])?>"><?=e($product['status'])?></span></td><td><?= $product['featured']?'<i class="fa-solid fa-star text-warning"></i>':'—' ?></td><td><?=e(date('d M Y',strtotime($product['updated_at'])))?></td><td><div class="table-actions"><a title="Edit" href="<?=e(url('admin/products/'.$product['id'].'/edit'))?>"><i class="fa-solid fa-pen"></i></a><form method="post" action="<?=e(url('admin/products/'.$product['id'].'/toggle'))?>"><?=csrf_field()?><button title="Toggle visibility"><i class="fa-solid fa-eye<?= $product['status']==='PUBLISHED' ? '-slash':'' ?>"></i></button></form><form method="post" action="<?=e(url('admin/products/'.$product['id'].'/delete'))?>" data-confirm="Delete this product permanently?"><?=csrf_field()?><button class="danger" title="Delete"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="6" class="empty-cell">No products found.</td></tr><?php endif;?></tbody></table></div></section>

